    /** Tests if $task resulted in an error. */
    public function had_error(): bool {}

    /**
     * Checks if $task's #GCancellable has been cancelled, and if so, sets $task's error
     * accordingly and completes the task (see g_task_return_pointer() for more discussion of
     * exactly what this means).
     */
    public function return_error_if_cancelled(): bool {}

    /**
     * Sets or clears $task's check-cancellable flag. If this is `true` (the default), then
     * g_task_propagate_pointer(), etc, and g_task_had_error() will check the task's #GCancellable
     * first, and if it has been cancelled, then they will consider the task to have returned an
     * "Operation was cancelled" error (%G_IO_ERROR_CANCELLED), regardless of any other error or
     * return value the task may have had.
     */
    public function set_check_cancellable(bool $check_cancellable): void {}

    /** Sets $task’s name, used in debugging and profiling. The name defaults to `null`. */
    public function set_name(?string $name): void {}

    /** Sets $task's priority. If you do not call this, it will default to %G_PRIORITY_DEFAULT. */
    public function set_priority(int $priority): void {}

    /**
     * Sets or clears $task's return-on-cancel flag. This is only meaningful for tasks run via
     * g_task_run_in_thread() or g_task_run_in_thread_sync().
     */
    public function set_return_on_cancel(bool $return_on_cancel): bool {}

    /** Sets $task’s name, used in debugging and profiling. */
    public function set_static_name(?string $name): void {}

    /**
     * The task's result, or a Gtk4\GError when it failed.
     *
     * A task has no result until something sets one; asking early is a GLib CRITICAL
     * (`task->result_set`) followed by a made-up zero, which is indistinguishable from a real
     * result. See the prelude for how "has a result" is decided.
     */
    public function propagate_boolean(): bool {}

    /**
     * The task's result, or a Gtk4\GError when it failed.
     *
     * A task has no result until something sets one; asking early is a GLib CRITICAL
     * (`task->result_set`) followed by a made-up zero, which is indistinguishable from a real
     * result. See the prelude for how "has a result" is decided.
     */
    public function propagate_int(): int {}

    /**
     * Set the task's result and schedule its callback.
     *
     * Marks the task as having an answer so propagate_boolean() can tell it apart from a fresh one
     * (see the prelude).
     */
    public function return_boolean(bool $result): void {}

    /**
     * Fail the task with $error and schedule its callback.
     *
     * Marks the task as having an answer so propagate_*() can tell it apart from a fresh one
     * (see the prelude).
     */
    public function return_error(GError $error): void {}

    /**
     * Set the task's result and schedule its callback.
     *
     * Marks the task as having an answer so propagate_int() can tell it apart from a fresh one
     * (see the prelude).
     */
    public function return_int(int $result): void {}

    /** @implementation-alias Gtk4\GAsyncResult::legacy_propagate_error */
    public function legacy_propagate_error(): bool {}
}

/**
 * A helper class for testing code which uses D-Bus without touching the user’s session bus.
 *
 * @property int $flags
 */
class GTestDBus extends GObject
{
    /** Create a new #GTestDBus object. */
    public function __construct(int $flags) {}

    /**
     * Unset DISPLAY and DBUS_SESSION_BUS_ADDRESS env variables to ensure the test won't use user's
     * session bus.
     */
    public static function unset(): void {}

    /**
     * Add a path where dbus-daemon will look up .service files. This can't be called after
     * g_test_dbus_up().
     */
    public function add_service_dir(string $path): void {}

    /** Stop the session bus started by g_test_dbus_up(). */
    public function down(): void {}

    /**
     * Get the address on which dbus-daemon is running. If g_test_dbus_up() has not been called
     * yet, `null` is returned. This can be used with g_dbus_connection_new_for_address().
     */
    public function get_bus_address(): ?string {}

    /** Get the flags of the #GTestDBus object. */
    public function get_flags(): int {}

    /** Stop the session bus started by g_test_dbus_up(). */
    public function stop(): void {}

    /**
     * Start a dbus-daemon instance and set DBUS_SESSION_BUS_ADDRESS. After this call, it is safe
     * for unit tests to start sending messages on the session bus.
     */
    public function up(): void {}
}

/**
 * Flags to define future #GTestDBus behaviour.
 */
final class GTestDBusFlags
{
    public const int NONE = 0;
}

